# Back up the robot's database (PostgreSQL in Docker) to backups\smart_campus-<date>.dump
#
#   powershell -ExecutionPolicy Bypass -File scripts\backup-db.ps1
#
# The dump holds the knowledge base, approvals, explainers, FAQs, places, conversations (text
# only) and robot runs. It contains no API keys. Keep it private: it includes visitor questions.
# backups\ is git-ignored. The speech cache (backend\data\tts_cache) is not in the dump: it is
# regenerated by prepare-phrases and prepare-explainers.

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
Set-Location $root
New-Item -ItemType Directory -Force -Path "backups" | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$name = "smart_campus-$stamp.dump"

# pg_dump runs inside the db container and writes there; docker cp brings the file out
# (a binary dump must not pass through the PowerShell pipeline, which would corrupt it).
# (no double quotes inside the command: Windows PowerShell 5 mangles them for native programs)
docker compose exec -T db sh -c 'pg_dump -U $POSTGRES_USER -d $POSTGRES_DB -Fc -f /tmp/backup.dump'
if ($LASTEXITCODE -ne 0) { throw "pg_dump failed. Is Docker running (docker compose up -d)?" }
$container = (docker compose ps -q db).Trim()
docker cp "${container}:/tmp/backup.dump" "backups\$name"
if ($LASTEXITCODE -ne 0) { throw "could not copy the dump out of the container" }
docker compose exec -T db rm -f /tmp/backup.dump

$size = [math]::Round((Get-Item "backups\$name").Length / 1MB, 2)
Write-Host "Backup written: backups\$name ($size MB)"
Write-Host "Restore it with: powershell -ExecutionPolicy Bypass -File scripts\restore-db.ps1 backups\$name"
